            </button>
            <button @click="addLine" class="tool-btn" title="添加线条">
              <span class="tool-icon">📏</span>
              <span class="tool-label">线条</span>
            </button>
            <button @click="addCircle" class="tool-btn" title="添加圆形">
              <span class="tool-icon">○</span>
              <span class="tool-label">圆形</span>
            </button>
          </div>
        </div>
        
        <!-- 辅助工具 -->
        <div class="toolbar-section">
          <h3>辅助工具</h3>
