              <span class="label">测量距离</span>
            </button>
            <button 
              @click="toggleLabelingMode" 
              class="tool-btn auxiliary-btn"
              :class="{ active: labelingMode.active }"
              title="添加说明标签"
            >
              <span class="icon">🏷️</span>
              <span class="label">添加标签</span>
            </button>
            <button @click="toggleSelectionMode" class="tool-btn auxiliary-btn" :class="{ active: selectionMode }" title="框选模式">
              <span class="icon">🖱️</span>
              <span class="label">框选</span>
            </button>
            <button @click="clearAllAuxiliary" class="tool-btn auxiliary-btn" title="清除所有辅助元素">
              <span class="icon">🗑️</span>
              <span class="label">清除辅助</span>
            </button>
            <button @click="alignSelectedElements('left')" class="tool-btn auxiliary-btn" :disabled="selectedElements.length < 2" title="左对齐">
              <span class="icon">◀</span>
              <span class="label">左对齐</span>
            </button>
            <button @click="alignSelectedElements('center')" class="tool-btn auxiliary-btn" :disabled="selectedElements.length < 2" title="居中对齐">
              <span class="icon">●</span>
              <span class="label">居中对齐</span>
            </button>
          </div>
          
          <!-- 测量模式提示 -->
          <div v-if="measuringMode.active" class="mode-hint">
            <p>📏 <strong>测量模式</strong></p>
            <p>点击两个设计元素测量距离</p>
            <p>已选择: {{ measuringMode.selectedElements.length }}/2</p>
            <button 
              @click="cancelMeasuring" 
              class="cancel-btn"
              :disabled="measuringMode.selectedElements.length === 0"
            >
              取消
            </button>
          </div>
          
          <!-- 标签模式提示 -->
          <div v-if="labelingMode.active" class="mode-hint">
            <p>🏷️ <strong>标签模式</strong></p>
            <p>点击设计元素添加说明标签</p>
            <p>点击画布空白处放置标签</p>
          </div>
          
          <!-- 框选模式提示 -->
          <div v-if="selectionMode" class="mode-hint">
            <p>🖱️ <strong>框选模式</strong></p>
            <p>在画布上拖动鼠标选择多个元素</p>
            <p>已选择: {{ selectedElements.length }}个元素</p>
          </div>
        </div>
        
        <!-- 箱型尺寸 -->
        <div class="toolbar-section">
          <h3>箱面尺寸</h3>
          <div class="box-sizes">
            <div class="size-presets">
              <button 
                v-for="preset in sizePresets" 
                :key="preset.id"
                @click="setBoxSize(preset.id)"
                class="size-preset-btn"
                :class="{ active: selectedSize === preset.id }"
                :title="preset.name"
              >
                <span class="size-name">{{ preset.name }}</span>
                <span class="size-dims">{{ preset.width }}×{{ preset.height }}mm</span>
              </button>
            </div>
            
            <div class="custom-size">
              <label>
                <span class="label-text">自定义尺寸</span>
                <div class="size-inputs">
                  <input 
                    type="number" 
                    v-model.number="customWidth" 
                    min="50" 
                    max="2000"
                    @change="applyCustomSize"
                    placeholder="宽度"
                  >
                  <span class="size-separator">×</span>
                  <input 
                    type="number" 
                    v-model.number="customHeight" 
                    min="50" 
                    max="2000"
                    @change="applyCustomSize"
                    placeholder="高度"
                  >
                  <span class="size-unit">mm</span>
                </div>
              </label>
            </div>
          </div>
        </div>

        <!-- 碰撞检测设置 -->
        <div class="toolbar-section">
          <h3>碰撞检测</h3>
          <div class="collision-settings">
            <div class="collision-toggle">
              <label class="toggle-switch">
                <input type="checkbox" v-model="collisionEnabled" @change="toggleCollision">
                <span class="toggle-slider"></span>
                <span class="toggle-text">{{ collisionEnabled ? '已开启' : '已关闭' }}</span>
              </label>
            </div>
            
            <div v-if="collisionEnabled" class="collision-options">
              <div class="option-group">
                <label class="option-label">
                  <input type="checkbox" v-model="collisionModes.preventOverlap">
                  <span class="option-text">阻止重叠</span>
                </label>
                <!-- <label class="option-label">
                  <input type="checkbox" v-model="collisionModes.showWarning">
                  <span class="option-text">显示警告</span>
                </label> -->
                <label class="option-label">
                  <input type="checkbox" v-model="collisionModes.snapToGrid">
                  <span class="option-text">网格对齐</span>
                </label>
                <label class="option-label">
                  <input type="checkbox" v-model="collisionModes.showMargin">
                  <span class="option-text">显示边距</span>
                </label>
              </div>
              
              <div class="margin-settings" v-if="collisionModes.showMargin">
                <label class="margin-label">
                  <span class="margin-text">安全边距:</span>
                  <input 
                    type="range" 
                    v-model.number="marginSize" 
                    min="0" 
                    max="50"
                    @input="updateMargin"
                  >
                  <span class="margin-value">{{ marginSize }}px</span>
                </label>
              </div>
              
              <!-- 碰撞统计 -->
              <div v-if="collisionStats.total > 0" class="collision-stats">
                <div class="stat-item">
                  <span class="stat-icon">⚠️</span>
                  <span class="stat-label">重叠元素:</span>
                  <span class="stat-value">{{ collisionStats.total }}个</span>
                </div>
                <div class="stat-item">
                  <span class="stat-icon">📦</span>
                  <span class="stat-label">超出边界:</span>
                  <span class="stat-value">{{ collisionStats.outOfBounds }}个</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        
        <!-- 图层管理 -->
        <div class="toolbar-section">
          <h3>图层管理</h3>
          <div class="layer-list">
            <div v-if="designElements.length === 0" class="empty-layers">
              暂无设计元素
            </div>
            <div 
              v-for="(element, index) in designElements.slice().reverse()" 
              :key="element.id"
              class="layer-item"
              :class="{ 
                selected: selectedElementId === element.id,
                colliding: element.colliding,
                hidden: element.hidden
              }"
              @click="selectDesignElement(element.id)"
              @dblclick="focusOnElement(element)"
              :title="getElementTooltip(element)"
            >
              <div class="layer-visibility">
                <button 
                  @click.stop="toggleElementVisibility(element)"
                  class="visibility-btn"
                >
                  {{ element.hidden ? '👁️‍🗨️' : '👁️' }}
                </button>
              </div>
              <div class="layer-info">
                <div class="layer-name">
                  <span class="layer-type">{{ getElementTypeName(element.type) }}</span>
                  <span class="layer-details" v-if="element.type === 'text'">
                    {{ element.props.text.substring(0, 8) }}{{ element.props.text.length > 8 ? '...' : '' }}
                  </span>
                </div>
                <div class="layer-position">
                  {{ element.x }}×{{ element.y }}
                </div>
              </div>
              <div class="layer-actions">
                <button @click.stop="bringToFront(element)" class="layer-action-btn" title="置顶">
                  ↑
                </button>
                <button @click.stop="sendToBack(element)" class="layer-action-btn" title="置底">
                  ↓
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      
      <!-- 中间画布 -->
      <div class="canvas-area">
        <div class="canvas-tools">
          <div class="zoom-controls">
            <button @click="zoomOut" class="zoom-btn" title="缩小">
              <span class="zoom-icon">−</span>
            </button>
            <div class="zoom-display">
              <span class="zoom-label">缩放:</span>
              <span class="zoom-value">{{ zoom }}%</span>
            </div>
            <button @click="zoomIn" class="zoom-btn" title="放大">
              <span class="zoom-icon">+</span>
            </button>
            <button @click="resetZoom" class="zoom-reset-btn" title="重置缩放">
              <span class="reset-icon">↺</span>
            </button>
          </div>
          
          <div class="canvas-info">
            <span class="size-display">
              <span class="size-label">画布:</span>
              <span class="size-value">{{ boxSize.width }}×{{ boxSize.height }}mm</span>
            </span>
            <span class="grid-display">
              <button @click="toggleGrid" class="grid-toggle-btn" :class="{ active: showGrid }" title="切换网格">
                <span class="grid-icon">#</span>
                <span class="grid-text">{{ showGrid ? '网格开' : '网格关' }}</span>
              </button>
            </span>
            <span class="selection-display" v-if="selectedElements.length > 0">
              已选择 {{ selectedElements.length }} 个元素
            </span>
            <span v-if="collisionEnabled && collisionStats.total > 0" class="collision-indicator">
              ⚠️ {{ collisionStats.total }}个碰撞
            </span>
          </div>
          
          <div class="view-controls">
            <button @click="centerView" class="view-btn" title="居中显示">
              <span class="view-icon">◎</span>
              <span class="view-text">居中</span>
            </button>
            <button @click="toggleRulers" class="view-btn" :class="{ active: showRulers }" title="切换标尺">
              <span class="view-icon">📐</span>
              <span class="view-text">标尺</span>
            </button>
            <button @click="toggleLabelsVisible" class="view-btn" :class="{ active: labelsVisible }" title="切换标签显示">
              <span class="view-icon">🏷️</span>
              <span class="view-text">标签</span>
            </button>
            <button @click="toggleGuides" class="view-btn" :class="{ active: showGuides }" title="切换参考线">
              <span class="view-icon">📏</span>
              <span class="view-text">参考线</span>
            </button>
          </div>
        </div>
        
        <div 
          class="canvas-container"
          ref="canvasContainer"
          @mousedown="handleCanvasMouseDown"
          @mousemove="handleCanvasMouseMove"
          @mouseup="handleCanvasMouseUp"
          @wheel.prevent="handleCanvasWheel"
        >
          <!-- 标尺 -->
          <div v-if="showRulers" class="canvas-rulers">
            <div class="horizontal-ruler">
              <div 
                v-for="mark in horizontalRulerMarks" 
                :key="mark"
                class="ruler-mark"
                :style="{ left: mark + 'px' }"
              >
                {{ mark }}
              </div>
            </div>
            <div class="vertical-ruler">
              <div 
                v-for="mark in verticalRulerMarks" 
                :key="mark"
                class="ruler-mark"
                :style="{ top: mark + 'px' }"
              >
                {{ mark }}
              </div>
            </div>
          </div>
          
          <div 
            class="box-boundary"
            ref="boxBoundary"
            :style="{
              width: boxSize.width + 'px',
              height: boxSize.height + 'px',
              transform: `scale(${zoom / 100})`,
              cursor: getCanvasCursor()
            }"
          >
            <!-- 网格背景 -->
            <div v-if="showGrid" class="grid-background"></div>
            
            <!-- 参考线 -->
            <div v-if="showGuides" class="guides">
              <div 
                v-for="(guide, index) in guides" 
                :key="index"
                class="guide"
                :style="{ 
                  left: guide.x + 'px', 
                  top: guide.y + 'px',
                  '--guide-type': guide.type
                }"
                @mousedown.stop="startGuideDrag(guide, $event)"
              ></div>
            </div>
            
            <!-- 设计元素 -->
            <div
              v-for="element in designElements"
              :key="element.id"
              class="design-element"
              :ref="el => setElementRef(element.id, el)"
              :class="{
                'selected': selectedElementId === element.id,
                'multi-selected': isMultiSelected(element),
                'colliding': element.colliding && collisionEnabled,
                'measuring-selected': isMeasuringSelected(element),
                'labeling-selected': labelingMode.targetElementId === element.id,
                'hidden': element.hidden,
                'dragging': dragState.type === 'move' && dragState.elements.some(el => el.id === element.id)
              }"
              :style="getElementStyle(element)"
              @mousedown.stop="handleElementMouseDown(element, $event)"
              @dblclick="editElement(element)"
              :title="getElementTooltip(element)"
            >
              <!-- 文本元素 -->
              <div v-if="element.type === 'text'" class="text-element">
                <div class="text-content">{{ element.props.text }}</div>
              </div>
              
              <!-- 矩形元素 -->
              <div v-if="element.type === 'rectangle'" class="rectangle-element">
                <div class="rectangle-content">
                  <div 
                    v-if="element.props.label" 
                    class="rectangle-label"
                    :style="{
                      fontSize: element.props.fontSize + 'px',
                      color: element.props.labelColor
                    }"
                  >
                    {{ element.props.label }}
                  </div>
                </div>
              </div>
              
              <!-- 二维码元素 -->
              <div v-if="element.type === 'qrcode'" class="qrcode-element">
                <div class="qrcode-content">
                  <div class="qrcode-pattern">
                    <div class="qr-corner tl"></div>
                    <div class="qr-corner tr"></div>
                    <div class="qr-corner bl"></div>
                    <div class="qr-dots"></div>
                  </div>
                  <div v-if="element.props.showLabel" class="qrcode-label">
                    {{ element.props.label || '二维码' }}
                  </div>
                </div>
              </div>
              
              <!-- 图片元素 -->
              <div v-if="element.type === 'image'" class="image-element">
                <div class="image-placeholder">
                  <span class="image-icon">🖼️</span>
                  <span class="image-label">{{ element.props.name || '图片' }}</span>
                </div>
              </div>
              
              <!-- 线条元素 -->
              <div v-if="element.type === 'line'" class="line-element">
                <div class="line-content"></div>
              </div>
              
              <!-- 圆形元素 -->
              <div v-if="element.type === 'circle'" class="circle-element">
                <div class="circle-content"></div>
              </div>
              
              <!-- 碰撞提示 -->
              <div 
                v-if="collisionEnabled && element.colliding" 
                class="collision-overlay"
              >
                ⚠️
              </div>
              
              <!-- 安全边距 -->
              <div 
                v-if="collisionEnabled && collisionModes.showMargin" 
                class="margin-overlay"
                :style="getMarginStyle(element)"
              ></div>
              
              <!-- 选中框 -->
              <div v-if="selectedElementId === element.id || isMultiSelected(element)" class="selection-box">
                <div 
                  class="resize-handle tl" 
                  @mousedown.stop="startResize(element, 'tl', $event)"
                ></div>
                <div 
                  class="resize-handle tr" 
                  @mousedown.stop="startResize(element, 'tr', $event)"
                ></div>
                <div 
                  class="resize-handle bl" 
                  @mousedown.stop="startResize(element, 'bl', $event)"
                ></div>
                <div 
                  class="resize-handle br" 
                  @mousedown.stop="startResize(element, 'br', $event)"
                ></div>
                <div 
                  class="resize-handle t" 
                  @mousedown.stop="startResize(element, 't', $event)"
                ></div>
                <div 
                  class="resize-handle r" 
                  @mousedown.stop="startResize(element, 'r', $event)"
                ></div>
                <div 
                  class="resize-handle b" 
                  @mousedown.stop="startResize(element, 'b', $event)"
                ></div>
                <div 
                  class="resize-handle l" 
                  @mousedown.stop="startResize(element, 'l', $event)"
                ></div>
                <div class="rotation-handle" @mousedown.stop="startRotate(element, $event)"></div>
              </div>
              
              <!-- 尺寸标签 -->
              <div v-if="selectedElementId === element.id" class="size-label">
                {{ element.width }}×{{ element.height }}
              </div>
              
              <!-- 旋转角度 -->
              <div v-if="selectedElementId === element.id && element.rotation" class="rotation-label">
                {{ Math.round(element.rotation) }}°
              </div>
            </div>
            
            <!-- 距离测量线 -->
            <div
              v-for="distance in distanceMeasurements"
              :key="distance.id"
              class="distance-measurement"
              :style="getDistanceStyle(distance)"
              @mousedown.stop="selectDistance(distance)"
              @dblclick.stop="removeDistance(distance)"
            >
              <div class="distance-line"></div>
              <div class="distance-arrow"></div>
              <div class="distance-label">{{ formatDistance(distance) }}</div>
              <div class="distance-endpoint start"></div>
              <div class="distance-endpoint end"></div>
              <div v-if="selectedDistanceId === distance.id" class="distance-selection"></div>
            </div>
            
            <!-- 说明标签 -->
            <div
              v-for="label in labels"
              :key="label.id"
              class="description-label"
              :class="{ 
                'hidden': !label.visible,
                'dragging': dragState.type === 'label' && dragState.label?.id === label.id
              }"
              :ref="el => setElementRef(label.id, el)"
              :style="getLabelStyle(label)"
              @mousedown.stop="selectLabel(label, $event)"
              @dblclick.stop="editLabel(label)"
            >
              <div class="label-header">
                <span class="label-title">{{ label.title }}</span>
                <button class="hide-btn" @click.stop="toggleLabelVisibility(label)">
                  {{ label.visible ? '👁️' : '👁️‍🗨️' }}
                </button>
              </div>
              <div class="label-content" v-if="label.description">
                {{ label.description }}
              </div>
              <div class="label-connector" :style="getLabelConnectorStyle(label)"></div>
              <div v-if="selectedLabelId === label.id" class="label-selection"></div>
            </div>
            
            <!-- 测量辅助线 -->
            <div v-if="measuringMode.active && measuringMode.selectedElements.length === 1" class="measurement-guide">
              <div class="guide-line" :style="getGuideLineStyle()"></div>
              <div class="guide-text">点击另一个元素完成测量</div>
            </div>
            
            <!-- 标签放置预览 -->
            <div v-if="labelingMode.active && labelingMode.targetElementId" class="label-preview">
              <div class="preview-line" :style="getPreviewLineStyle()"></div>
              <div class="preview-text">点击放置标签</div>
            </div>
            
            <!-- 选择框 -->
            <div 
              v-if="selectionMode && isSelecting" 
              class="selection-rect"
              :style="selectionRectStyle"
            ></div>
            
            <!-- 标签放置区域指示器 -->
            <div class="label-drop-zone" :class="{ active: showDropZone }"></div>
          </div>
        </div>
      </div>
      
      <!-- 右侧属性面板 -->
      <div class="right-properties">
        <!-- 多选属性 -->
        <div v-if="selectedElements.length > 1" class="multi-properties">
          <h3>多选元素 ({{ selectedElements.length }}个)</h3>
          <div class="multi-actions">
            <button @click="groupSelectedElements" class="multi-btn">
              <span class="multi-icon">👥</span>
              <span class="multi-text">组合</span>
            </button>
            <button @click="alignSelectedElements('left')" class="multi-btn">
              <span class="multi-icon">◀</span>
              <span class="multi-text">左对齐</span>
            </button>
            <button @click="alignSelectedElements('center')" class="multi-btn">
              <span class="multi-icon">●</span>
              <span class="multi-text">水平居中</span>
            </button>
            <button @click="alignSelectedElements('right')" class="multi-btn">
              <span class="multi-icon">▶</span>
              <span class="multi-text">右对齐</span>
            </button>
            <button @click="alignSelectedElements('top')" class="multi-btn">
              <span class="multi-icon">▲</span>
              <span class="multi-text">顶对齐</span>
            </button>
            <button @click="alignSelectedElements('middle')" class="multi-btn">
              <span class="multi-icon">●</span>
              <span class="multi-text">垂直居中</span>
            </button>
            <button @click="alignSelectedElements('bottom')" class="multi-btn">
              <span class="multi-icon">▼</span>
              <span class="multi-text">底对齐</span>
            </button>
            <button @click="distributeSelectedElements('horizontal')" class="multi-btn">
