<script>
import { ref, reactive, onMounted, onUnmounted, computed, watch, nextTick } from 'vue'

export default {
  name: 'HomeView',
  
  setup() {
    // 状态管理
    const state = {
      // 基础状态
      zoom: ref(100),
      selectedSize: ref('standard'),
      designElements: ref([]),
      selectedElementId: ref(null),
      selectedElements: ref([]),
      selectedDistanceId: ref(null),
      selectedLabelId: ref(null),
      isDragging: ref(false),
      isResizing: ref(false),
      isRotating: ref(false),
      isSelecting: ref(false),
      showGrid: ref(true),
      showRulers: ref(true),
      showGuides: ref(true),
      labelsVisible: ref(true),
      selectionMode: ref(false),
      customWidth: ref(400),
      customHeight: ref(300),
      showMeasurementsPanel: ref(false),
      showLabelsPanel: ref(false),
      showExportPanel: ref(false),
      isFullscreen: ref(false),
      cursorPosition: reactive({ x: 0, y: 0 }),
      selectionRect: reactive({ x: 0, y: 0, width: 0, height: 0 }),
      showDropZone: ref(false),
      
      // 操作历史
      history: reactive({
        past: [],
        future: [],
        maxSteps: 50
      }),
      
      // 尺寸预设
      sizePresets: [
        { id: 'small', name: '小箱', width: 300, height: 200 },
        { id: 'standard', name: '标准箱', width: 400, height: 300 },
        { id: 'large', name: '大箱', width: 500, height: 400 },
        { id: 'custom', name: '自定义', width: 400, height: 300 }
      ],
      
      // 箱型尺寸
      boxSize: ref({ width: 400, height: 300 }),
      
      // 测量模式
      measuringMode: reactive({
        active: false,
        selectedElements: []
      }),
      
      // 标签模式
      labelingMode: reactive({
        active: false,
        targetElementId: null,
        placementPosition: null
      }),
      
      // 距离测量数据
      distanceMeasurements: ref([]),
      
      // 说明标签数据
      labels: ref([]),
      
      // 碰撞检测状态
      collisionEnabled: ref(true),
      collisionModes: reactive({
        preventOverlap: true,
        showWarning: true,
        snapToGrid: true,
        showMargin: false
      }),
      marginSize: ref(10),
      
      // 拖动状态
      dragState: reactive({
        type: null, // 'move', 'resize', 'rotate', 'select', 'label'
        element: null,
        elements: [],
        label: null,
        guide: null,
        startX: 0,
        startY: 0,
        originalX: 0,
        originalY: 0,
        originalWidth: 0,
        originalHeight: 0,
        originalRotation: 0,
        resizeDirection: null,
        centerX: 0,
        centerY: 0,
        startAngle: 0
      }),
      
      // 参考线
      guides: ref([
        { type: 'horizontal', x: 0, y: 100 },
        { type: 'vertical', x: 100, y: 0 }
      ]),
      
      // 最近项目
      recentProjects: ref([]),
      
      // 导出设置
      exportFormat: ref('png'),
      exportSettings: reactive({
        includeBackground: true,
        includeGrid: false,
        includeLabels: true,
        includeMeasurements: false,
        quality: 90
      })
    }

    // 存储元素DOM引用的映射
    const elementRefs = reactive({})
    
    // 存储画布引用
    const canvasContainer = ref(null)
    const boxBoundary = ref(null)

    // 防抖函数
    const debounce = (fn, delay) => {
      let timeoutId
      return function(...args) {
        clearTimeout(timeoutId)
        timeoutId = setTimeout(() => fn.apply(this, args), delay)
      }
    }

    // 计算属性
    const computedProps = {
      selectedElement: computed(() => {
        return state.designElements.value.find(el => el.id === state.selectedElementId.value)
      }),
      
      selectedDistance: computed(() => {
        return state.distanceMeasurements.value.find(d => d.id === state.selectedDistanceId.value)
      }),
      
      selectedLabel: computed(() => {
        return state.labels.value.find(l => l.id === state.selectedLabelId.value)
      }),
      
      collisionStats: computed(() => {
        const collidingElements = state.designElements.value.filter(el => el.colliding)
        const outOfBoundsElements = state.designElements.value.filter(el => 
          el.x < 0 || 
          el.y < 0 || 
          el.x + el.width > state.boxSize.value.width || 
          el.y + el.height > state.boxSize.value.height
        )
        
        return {
          total: collidingElements.length,
          outOfBounds: outOfBoundsElements.length
        }
      }),
      
      multiStats: computed(() => {
        if (state.selectedElements.value.length === 0) {
          return { minX: 0, maxX: 0, minY: 0, maxY: 0 }
        }
        
        const xs = state.selectedElements.value.map(el => el.x)
        const ys = state.selectedElements.value.map(el => el.y)
        const widths = state.selectedElements.value.map(el => el.x + el.width)
        const heights = state.selectedElements.value.map(el => el.y + el.height)
        
        return {
          minX: Math.min(...xs),
          maxX: Math.max(...widths),
          minY: Math.min(...ys),
          maxY: Math.max(...heights)
        }
      }),
      
      canUndo: computed(() => state.history.past.length > 0),
      canRedo: computed(() => state.history.future.length > 0),
      
      horizontalRulerMarks: computed(() => {
        const marks = []
        const step = 50
        for (let i = 0; i <= state.boxSize.value.width; i += step) {
          marks.push(i)
        }
        return marks
      }),
      
      verticalRulerMarks: computed(() => {
        const marks = []
        const step = 50
        for (let i = 0; i <= state.boxSize.value.height; i += step) {
          marks.push(i)
        }
        return marks
      }),
      
      selectionRectStyle: computed(() => ({
        left: state.selectionRect.x + 'px',
        top: state.selectionRect.y + 'px',
        width: state.selectionRect.width + 'px',
        height: state.selectionRect.height + 'px'
      })),
      
      previewBoxStyle: computed(() => ({
        width: '100%',
        height: '200px',
        border: '1px solid #ddd',
        position: 'relative',
        backgroundColor: state.exportSettings.includeBackground ? '#fff' : 'transparent'
      }))
    }

    // 工具函数
    const utils = {
      // 生成唯一ID
      generateId: () => Date.now() + Math.random().toString(36).substr(2, 9),
      
      // 保存历史状态（修复循环引用问题）
      saveHistory: () => {
        const snapshot = {
          elements: state.designElements.value.map(el => {
            // 创建元素的浅拷贝，避免引用问题
            const elementCopy = { ...el }
            // 移除collisions数组中的循环引用（只保留必要信息）
            if (elementCopy.collisions) {
              elementCopy.collisions = elementCopy.collisions.map(collision => {
                // 只保留必要信息，移除对元素的直接引用
                const { element, ...rest } = collision
                return {
                  ...rest,
                  elementId: collision.elementId || (element ? element.id : null)
                }
              })
            }
            return elementCopy
          }),
          measurements: JSON.parse(JSON.stringify(state.distanceMeasurements.value)),
          labels: JSON.parse(JSON.stringify(state.labels.value))
        }
        
        state.history.past.push(snapshot)
        if (state.history.past.length > state.history.maxSteps) {
          state.history.past.shift()
        }
        state.history.future = []
      },
      
      // 格式化日期
      formatDate: (date) => {
        const d = new Date(date)
        return `${d.getFullYear()}-${(d.getMonth() + 1).toString().padStart(2, '0')}-${d.getDate().toString().padStart(2, '0')}`
      },
      
      // 获取元素类型名称
      getElementTypeName: (type) => {
        const names = {
          text: '文本',
          rectangle: '矩形',
          qrcode: '二维码',
          image: '图片',
          line: '线条',
          circle: '圆形'
        }
        return names[type] || type
      },
      
      // 获取距离类型名称
      getDistanceTypeName: (type) => {
        const names = {
          horizontal: '水平距离',
          vertical: '垂直距离',
          diagonal: '对角距离',
          overlap: '重叠'
        }
        return names[type] || type
      },
      
      // 检查是否在多选范围内
      isMultiSelected: (element) => {
        return state.selectedElements.value.some(el => el.id === element.id)
      }
    }

    // 设置元素引用
    const setElementRef = (elementId, el) => {
      if (el) {
        elementRefs[elementId] = el
      }
    }

    // 碰撞检测函数（修复循环引用问题）
    const checkAllCollisions = () => {
      if (!state.collisionEnabled.value) {
        // 如果碰撞检测关闭，清除所有碰撞状态
        state.designElements.value.forEach(el => {
          el.colliding = false
          el.collisions = []
        })
        return
      }
      
      // 重置所有元素的碰撞状态
      state.designElements.value.forEach(el => {
        el.colliding = false
        el.collisions = []
      })
      
      // 检查所有元素对
      for (let i = 0; i < state.designElements.value.length; i++) {
        for (let j = i + 1; j < state.designElements.value.length; j++) {
          const element1 = state.designElements.value[i]
          const element2 = state.designElements.value[j]
          
          // 跳过隐藏的元素
          if (element1.hidden || element2.hidden) continue
          
          const margin = state.collisionModes.showMargin ? state.marginSize.value : 0
          
          const rect1 = {
            left: element1.x - margin,
            right: element1.x + element1.width + margin,
            top: element1.y - margin,
            bottom: element1.y + element1.height + margin
          }
          
          const rect2 = {
            left: element2.x - margin,
            right: element2.x + element2.width + margin,
            top: element2.y - margin,
            bottom: element2.y + element2.height + margin
          }
          
          // 检查是否碰撞
          const collision = !(
            rect1.right <= rect2.left ||
            rect1.left >= rect2.right ||
            rect1.bottom <= rect2.top ||
            rect1.top >= rect2.bottom
          )
          
          if (collision) {
            const overlapX = Math.max(0, Math.min(rect1.right, rect2.right) - Math.max(rect1.left, rect2.left))
            const overlapY = Math.max(0, Math.min(rect1.bottom, rect2.bottom) - Math.max(rect1.top, rect2.top))
            const overlapArea = overlapX * overlapY
            
            element1.colliding = true
            element2.colliding = true
            
            if (!element1.collisions) element1.collisions = []
            if (!element2.collisions) element2.collisions = []
            
            // 只存储元素ID而不是整个元素对象，避免循环引用
            element1.collisions.push({
              elementId: element2.id,
              elementType: element2.type,
              overlapArea,
              overlapX,
              overlapY
            })
            
            element2.collisions.push({
              elementId: element1.id,
              elementType: element1.type,
              overlapArea,
              overlapX,
              overlapY
            })
          }
        }
      }
      
      // 额外检查元素是否超出画布边界
      state.designElements.value.forEach(element => {
        if (!element.colliding) {
          // 检查是否超出边界
          const outOfBounds = 
            element.x < 0 ||
            element.y < 0 ||
            element.x + element.width > state.boxSize.value.width ||
            element.y + element.height > state.boxSize.value.height
          
          if (outOfBounds) {
            element.colliding = true
            if (!element.collisions) element.collisions = []
            element.collisions.push({
              elementId: null, // 表示边界
              elementType: null,
              overlapArea: 0,
              overlapX: 0,
              overlapY: 0,
              isBoundary: true
            })
          }
        }
      })
    }

    // 获取碰撞列表（修复循环引用问题）
    const getCollisions = (element) => {
      if (!element || !element.collisions) return []
      
      return element.collisions.map(collision => {
        // 根据ID查找元素（避免存储循环引用）
        const targetElement = collision.elementId ? 
          state.designElements.value.find(el => el.id === collision.elementId) : 
          null
        
        return {
          ...collision,
          element: targetElement // 实时查找，不存储引用
        }
      })
    }

    // 核心功能
    const core = {
      // 添加设计元素
      addText: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'text',
          x: 50,
          y: 50,
          width: 120,
          height: 40,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            text: '新文本',
            fontSize: 16,
            color: '#000000',
            fontWeight: 'normal',
            textAlign: 'center',
            fontFamily: 'Arial, sans-serif'
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        checkAllCollisions()
        utils.saveHistory()
      },
      
      addRectangle: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'rectangle',
          x: 100,
          y: 100,
          width: 150,
          height: 100,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            label: '矩形标签',
            fontSize: 14,
            labelColor: '#000000',
            fillColor: 'rgba(255, 255, 255, 0.1)',
            strokeColor: '#000000',
            strokeWidth: 2,
            borderRadius: 0
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        checkAllCollisions()
        utils.saveHistory()
      },
      
      addQrCode: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'qrcode',
          x: 200,
          y: 200,
          width: 100,
          height: 100,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            content: 'https://example.com',
            showLabel: true,
            label: '二维码',
            foregroundColor: '#000000',
            backgroundColor: '#ffffff'
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        checkAllCollisions()
        utils.saveHistory()
      },
      
      addImage: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'image',
          x: 150,
          y: 150,
          width: 120,
          height: 90,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            name: '图片',
            url: '',
            keepAspectRatio: true
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        checkAllCollisions()
        utils.saveHistory()
      },
      
      addLine: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'line',
          x: 50,
          y: 200,
          width: 100,
          height: 2,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            color: '#000000',
            width: 2,
            style: 'solid'
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        utils.saveHistory()
      },
      
      addCircle: () => {
        const newElement = {
          id: utils.generateId(),
          type: 'circle',
          x: 100,
          y: 200,
          width: 100,
          height: 100,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            fillColor: 'rgba(255, 255, 255, 0.1)',
            strokeColor: '#000000',
            strokeWidth: 2
          }
        }
        state.designElements.value.push(newElement)
        core.selectDesignElement(newElement.id)
        checkAllCollisions()
        utils.saveHistory()
      },
      
      // 计算两个元素之间的最近距离 - 修复版本
      calculateClosestDistance: (element1, element2) => {
        const rect1 = {
          left: element1.x,
          right: element1.x + element1.width,
          top: element1.y,
          bottom: element1.y + element1.height,
          centerX: element1.x + element1.width / 2,
          centerY: element1.y + element1.height / 2
        }
        
        const rect2 = {
          left: element2.x,
          right: element2.x + element2.width,
          top: element2.y,
          bottom: element2.y + element2.height,
          centerX: element2.x + element2.width / 2,
          centerY: element2.y + element2.height / 2
        }
        
        // 检查是否有重叠
        const overlapX = Math.max(0, Math.min(rect1.right, rect2.right) - Math.max(rect1.left, rect2.left))
        const overlapY = Math.max(0, Math.min(rect1.bottom, rect2.bottom) - Math.max(rect1.top, rect2.top))
        
        if (overlapX > 0 && overlapY > 0) {
          // 元素重叠
          return {
            element1Id: element1.id,
            element2Id: element2.id,
            type: 'overlap',
            startX: rect1.centerX,
            startY: rect1.centerY,
            endX: rect2.centerX,
            endY: rect2.centerY,
            value: 0,
            verticalOffset: 0,
            horizontalOffset: 0
          }
        }
        
        // 判断元素的相对位置关系
        const isRect1AboveRect2 = rect1.bottom <= rect2.top
        const isRect1BelowRect2 = rect1.top >= rect2.bottom
        const isRect1LeftOfRect2 = rect1.right <= rect2.left
        const isRect1RightOfRect2 = rect1.left >= rect2.right
        
        let distanceType = ''
        let distance = 0
        let startX = 0, startY = 0, endX = 0, endY = 0
        let verticalOffset = 0
        let horizontalOffset = 0
        
        // 情况1：垂直对齐（上下关系）
        if (isRect1AboveRect2 || isRect1BelowRect2) {
          // 计算水平重叠
          const horizontalOverlap = Math.min(rect1.right, rect2.right) - Math.max(rect1.left, rect2.left)
          
          if (horizontalOverlap > 0) {
            // 有水平重叠，计算垂直距离
            distanceType = 'vertical'
            const centerX = (Math.max(rect1.left, rect2.left) + Math.min(rect1.right, rect2.right)) / 2
            
            if (isRect1AboveRect2) {
              // rect1在上方
              startX = centerX
              startY = rect1.bottom
              endX = centerX
              endY = rect2.top
              distance = rect2.top - rect1.bottom
            } else {
              // rect1在下方
              startX = centerX
              startY = rect2.bottom
              endX = centerX
              endY = rect1.top
              distance = rect1.top - rect2.bottom
            }
            
            horizontalOffset = Math.abs(rect1.centerX - rect2.centerX)
          } else {
            // 没有水平重叠，计算对角距离
            distanceType = 'diagonal'
            
            if (isRect1AboveRect2) {
              // rect1在左上方或右上方
              if (rect1.right <= rect2.left) {
                // rect1在左上方
                startX = rect1.right
                startY = rect1.bottom
                endX = rect2.left
                endY = rect2.top
              } else {
                // rect1在右上方
                startX = rect1.left
                startY = rect1.bottom
                endX = rect2.right
                endY = rect2.top
              }
            } else {
              // rect1在左下方或右下方
              if (rect1.right <= rect2.left) {
                // rect1在左下方
                startX = rect1.right
                startY = rect1.top
                endX = rect2.left
                endY = rect2.bottom
              } else {
                // rect1在右下方
                startX = rect1.left
                startY = rect1.top
                endX = rect2.right
                endY = rect2.bottom
              }
            }
            
            const dx = endX - startX
            const dy = endY - startY
            distance = Math.sqrt(dx * dx + dy * dy)
          }
        }
        // 情况2：水平对齐（左右关系）
        else if (isRect1LeftOfRect2 || isRect1RightOfRect2) {
          // 计算垂直重叠
          const verticalOverlap = Math.min(rect1.bottom, rect2.bottom) - Math.max(rect1.top, rect2.top)
          
          if (verticalOverlap > 0) {
            // 有垂直重叠，计算水平距离
            distanceType = 'horizontal'
            const centerY = (Math.max(rect1.top, rect2.top) + Math.min(rect1.bottom, rect2.bottom)) / 2
            
            if (isRect1LeftOfRect2) {
              // rect1在左边
              startX = rect1.right
              startY = centerY
              endX = rect2.left
              endY = centerY
              distance = rect2.left - rect1.right
            } else {
              // rect1在右边
              startX = rect2.right
              startY = centerY
              endX = rect1.left
              endY = centerY
              distance = rect1.left - rect2.right
            }
            
            verticalOffset = Math.abs(rect1.centerY - rect2.centerY)
          } else {
            // 没有垂直重叠，计算对角距离（已经在上面处理过了）
            distanceType = 'diagonal'
            // 使用已有的对角距离计算逻辑
            const distances = [
              { type: 'top-left', dx: rect2.right - rect1.left, dy: rect2.bottom - rect1.top },
              { type: 'top-right', dx: rect2.left - rect1.right, dy: rect2.bottom - rect1.top },
              { type: 'bottom-left', dx: rect2.right - rect1.left, dy: rect2.top - rect1.bottom },
              { type: 'bottom-right', dx: rect2.left - rect1.right, dy: rect2.top - rect1.bottom }
            ]
            
            // 找到最小距离
            let minDistance = Infinity
            let bestDirection = null
            
            distances.forEach(dir => {
              const dist = Math.sqrt(dir.dx * dir.dx + dir.dy * dir.dy)
              if (dist < minDistance) {
                minDistance = dist
                bestDirection = dir.type
              }
            })
            
            distance = minDistance
            
            // 根据方向设置起点和终点
            switch (bestDirection) {
              case 'top-left':
                startX = rect1.left
                startY = rect1.top
                endX = rect2.right
                endY = rect2.bottom
                break
              case 'top-right':
                startX = rect1.right
                startY = rect1.top
                endX = rect2.left
                endY = rect2.bottom
                break
              case 'bottom-left':
                startX = rect1.left
                startY = rect1.bottom
                endX = rect2.right
                endY = rect2.top
                break
              case 'bottom-right':
                startX = rect1.right
                startY = rect1.bottom
                endX = rect2.left
                endY = rect2.top
                break
            }
          }
        }
        
        return {
          element1Id: element1.id,
          element2Id: element2.id,
          type: distanceType,
          startX,
          startY,
          endX,
          endY,
          value: Math.round(distance),
          verticalOffset: Math.round(verticalOffset),
          horizontalOffset: Math.round(horizontalOffset),
          visible: true
        }
      },
      
      // 更新所有距离测量
      updateAllDistanceMeasurements: () => {
        state.distanceMeasurements.value.forEach(distance => {
          const element1 = state.designElements.value.find(el => el.id === distance.element1Id)
          const element2 = state.designElements.value.find(el => el.id === distance.element2Id)
          
          if (element1 && element2) {
            const newDistance = core.calculateClosestDistance(element1, element2)
            Object.assign(distance, newDistance)
          }
        })
      },
      
      // 获取元素名称
      getElementName: (elementId) => {
        const element = state.designElements.value.find(el => el.id === elementId)
        if (!element) return '未知元素'
        
        switch (element.type) {
          case 'text':
            return `文本: ${element.props.text.substring(0, 10)}${element.props.text.length > 10 ? '...' : ''}`
          case 'rectangle':
            return `矩形${element.props.label ? `: ${element.props.label}` : ''}`
          case 'qrcode':
            return `二维码${element.props.label ? `: ${element.props.label}` : ''}`
          case 'image':
            return `图片${element.props.name ? `: ${element.props.name}` : ''}`
          case 'line':
            return '线条'
          case 'circle':
            return '圆形'
          default:
            return element.type
        }
      },
      
      // 检查是否为测量选中的元素
      isMeasuringSelected: (element) => {
        return state.measuringMode.selectedElements.some(el => el.id === element.id)
      },
      
      // 切换测量模式
      toggleMeasuringMode: () => {
        state.measuringMode.active = !state.measuringMode.active
        if (state.measuringMode.active) {
          state.labelingMode.active = false
          state.selectionMode = false
          state.measuringMode.selectedElements = []
        } else {
          state.measuringMode.selectedElements = []
        }
      },
      
      // 切换标签模式
      toggleLabelingMode: () => {
        state.labelingMode.active = !state.labelingMode.active
        if (state.labelingMode.active) {
          state.measuringMode.active = false
          state.selectionMode = false
          state.labelingMode.targetElementId = null
          state.labelingMode.placementPosition = null
        } else {
          state.labelingMode.targetElementId = null
          state.labelingMode.placementPosition = null
        }
      },
      
      // 切换选择模式
      toggleSelectionMode: () => {
        state.selectionMode = !state.selectionMode
        if (state.selectionMode) {
          state.measuringMode.active = false
          state.labelingMode.active = false
        }
      },
      
      // 取消测量
      cancelMeasuring: () => {
        state.measuringMode.selectedElements = []
      },
      
      // 清除所有辅助元素
      clearAllAuxiliary: () => {
        if (confirm('确定要清除所有测量线和标签吗？')) {
          state.distanceMeasurements.value = []
          state.labels.value = []
          state.selectedDistanceId.value = null
          state.selectedLabelId.value = null
          utils.saveHistory()
        }
      },
      
      // 清空所有距离测量
      clearAllDistances: () => {
        if (confirm('确定要清空所有距离测量吗？')) {
          state.distanceMeasurements.value = []
          state.selectedDistanceId.value = null
          utils.saveHistory()
        }
      },
      
      // 处理元素鼠标按下
      handleElementMouseDown: (element, event) => {
        if (element.locked) return
        
        if (state.measuringMode.active) {
          // 测量模式
          if (!state.measuringMode.selectedElements.some(el => el.id === element.id)) {
            state.measuringMode.selectedElements.push(element)
            
            if (state.measuringMode.selectedElements.length === 2) {
              const element1 = state.measuringMode.selectedElements[0]
              const element2 = state.measuringMode.selectedElements[1]
              
              const distance = core.calculateClosestDistance(element1, element2)
              distance.id = utils.generateId()
              distance.color = '#007bff'
              
              state.distanceMeasurements.value.push(distance)
              
              state.measuringMode.selectedElements = []
              state.measuringMode.active = false
              
              core.selectDistance(distance.id)
              utils.saveHistory()
            }
          }
        } else if (state.labelingMode.active) {
          // 标签模式
          state.labelingMode.targetElementId = element.id
          state.labelingMode.placementPosition = {
            x: element.x + element.width + 50,
            y: element.y + element.height / 2
          }
        } else if (event.shiftKey || state.selectionMode) {
          // 多选模式
          if (utils.isMultiSelected(element)) {
            state.selectedElements.value = state.selectedElements.value.filter(el => el.id !== element.id)
            if (state.selectedElements.value.length === 0) {
              state.selectedElementId.value = null
            }
          } else {
            state.selectedElements.value.push(element)
          }
        } else {
          // 单选模式
          core.selectDesignElement(element.id)
          
          // 检查是否在测量模式下，如果是则允许拖动
          if (state.measuringMode.selectedElements.length > 0 || !state.measuringMode.active) {
            core.startDrag(element, event)
          }
        }
      },
      
      // 选择设计元素
      selectDesignElement: (elementId) => {
        state.selectedElementId.value = elementId
        state.selectedDistanceId.value = null
        state.selectedLabelId.value = null
        state.selectedElements.value = state.designElements.value.filter(el => el.id === elementId)
      },
      
      // 选择元素（用于碰撞列表点击）
      selectElement: (element) => {
        if (element) {
          core.selectDesignElement(element.id)
        }
      },
      
      // 选择距离测量
      selectDistance: (distance) => {
        if (typeof distance === 'object') {
          state.selectedDistanceId.value = distance.id
        } else {
          state.selectedDistanceId.value = distance
        }
        state.selectedElementId.value = null
        state.selectedLabelId.value = null
        state.selectedElements.value = []
      },
      
      // 删除距离测量
      removeDistance: (distance) => {
        state.distanceMeasurements.value = state.distanceMeasurements.value.filter(d => d.id !== distance.id)
        if (state.selectedDistanceId.value === distance.id) {
          state.selectedDistanceId.value = null
        }
        utils.saveHistory()
      },
      
      // 切换测量可见性
      toggleMeasurementVisible: (distance) => {
        distance.visible = !distance.visible
      },
      
      // 选择标签
      selectLabel: (label, event) => {
        if (typeof label === 'object') {
          state.selectedLabelId.value = label.id
        } else {
          state.selectedLabelId.value = label
        }
        state.selectedElementId.value = null
        state.selectedDistanceId.value = null
        state.selectedElements.value = []
        
        if (event) {
          core.startDragLabel(label, event)
        }
      },
      
      // 编辑标签
      editLabel: (label) => {
        const newTitle = prompt('输入标签标题:', label.title)
        if (newTitle !== null) {
          label.title = newTitle
          core.updateLabel()
        }
      },
      
      // 删除标签
      deleteLabel: (label) => {
        state.labels.value = state.labels.value.filter(l => l.id !== label.id)
        if (state.selectedLabelId.value === label.id) {
          state.selectedLabelId.value = null
        }
        utils.saveHistory()
      },
      
      // 切换标签可见性
      toggleLabelVisibility: (label) => {
        label.visible = !label.visible
        core.updateLabel()
      },
      
      // 显示所有标签
      showAllLabels: () => {
        state.labels.value.forEach(label => {
          label.visible = true
        })
      },
      
      // 隐藏所有标签
      hideAllLabels: () => {
        state.labels.value.forEach(label => {
          label.visible = false
        })
      },
      
      // 开始拖动元素
      startDrag: (element, event) => {
        state.isDragging.value = true
        state.dragState.type = 'move'
        state.dragState.element = element
        state.dragState.elements = state.selectedElements.value.length > 1 ? 
          [...state.selectedElements.value] : [element]
        state.dragState.startX = event.clientX
        state.dragState.startY = event.clientY
        
        state.dragState.elements.forEach(el => {
          el.originalX = el.x
          el.originalY = el.y
        })
        
        // 添加拖动样式
        state.dragState.elements.forEach(el => {
          if (elementRefs[el.id]) {
            elementRefs[el.id].classList.add('dragging')
          }
        })
      },
      
      // 开始拖动标签
      startDragLabel: (label, event) => {
        event.stopPropagation()
        state.isDragging.value = true
        state.dragState.type = 'label'
        state.dragState.label = label
        state.dragState.startX = event.clientX
        state.dragState.startY = event.clientY
        state.dragState.originalX = label.x
        state.dragState.originalY = label.y
        
        // 添加拖动样式
        if (elementRefs[label.id]) {
          elementRefs[label.id].classList.add('dragging')
        }
      },
      
      // 开始调整大小
      startResize: (element, direction, event) => {
        event.stopPropagation()
        state.isResizing.value = true
        state.dragState.type = 'resize'
        state.dragState.element = element
        state.dragState.resizeDirection = direction
        state.dragState.startX = event.clientX
        state.dragState.startY = event.clientY
        state.dragState.originalX = element.x
        state.dragState.originalY = element.y
        state.dragState.originalWidth = element.width
        state.dragState.originalHeight = element.height
      },
      
      // 开始旋转
      startRotate: (element, event) => {
        event.stopPropagation()
        event.preventDefault()
        
        state.isRotating.value = true
        state.dragState.type = 'rotate'
        state.dragState.element = element
        state.dragState.startX = event.clientX
        state.dragState.startY = event.clientY
        state.dragState.originalRotation = element.rotation || 0
        
        // 获取元素中心点
        const elementCenterX = element.x + element.width / 2
        const elementCenterY = element.y + element.height / 2
        
        // 获取画布边界和缩放信息
        if (boxBoundary.value) {
          const boxRect = boxBoundary.value.getBoundingClientRect()
          const zoomRatio = state.zoom.value / 100
          
          // 计算元素中心点在屏幕上的坐标
          const centerX = boxRect.left + elementCenterX * zoomRatio
          const centerY = boxRect.top + elementCenterY * zoomRatio
          
          state.dragState.centerX = centerX
          state.dragState.centerY = centerY
          
          // 计算初始角度
          const dx = event.clientX - centerX
          const dy = event.clientY - centerY
          state.dragState.startAngle = Math.atan2(dy, dx) * 180 / Math.PI
        }
      },
      
      // 开始拖动参考线
      startGuideDrag: (guide, event) => {
        state.isDragging.value = true
        state.dragState.type = 'guide'
        state.dragState.guide = guide
        state.dragState.startX = event.clientX
        state.dragState.startY = event.clientY
        state.dragState.originalX = guide.x
        state.dragState.originalY = guide.y
      },
      
      // 处理画布鼠标按下
      handleCanvasMouseDown: (event) => {
        if (state.labelingMode.active && state.labelingMode.targetElementId && state.labelingMode.placementPosition) {
          // 放置标签
          const targetElement = state.designElements.value.find(el => el.id === state.labelingMode.targetElementId)
          if (targetElement) {
            const newLabel = {
              id: utils.generateId(),
              elementId: targetElement.id,
              x: state.labelingMode.placementPosition.x,
              y: state.labelingMode.placementPosition.y,
              width: 150,
              height: 80,
              title: '新标签',
              description: '点击编辑说明文字',
              color: '#ff9900',
              visible: true,
              connectorLength: 30
            }
            
            state.labels.value.push(newLabel)
            core.selectLabel(newLabel.id)
            
            state.labelingMode.targetElementId = null
            state.labelingMode.placementPosition = null
            state.labelingMode.active = false
            utils.saveHistory()
          }
        } else if (state.selectionMode) {
          // 开始框选
          state.isSelecting.value = true
          state.dragState.type = 'select'
          state.dragState.startX = event.clientX
          state.dragState.startY = event.clientY
          state.selectionRect.x = event.offsetX
          state.selectionRect.y = event.offsetY
          state.selectionRect.width = 0
          state.selectionRect.height = 0
        } else if (event.target.classList.contains('box-boundary') || 
                   event.target.classList.contains('canvas-container')) {
          // 点击画布空白处：取消所有选择
          state.selectedElementId.value = null
          state.selectedDistanceId.value = null
          state.selectedLabelId.value = null
          state.selectedElements.value = []
          state.measuringMode.selectedElements = []
        }
      },
      
      // 处理画布鼠标移动
      handleCanvasMouseMove: (event) => {
        // 更新光标位置
        const rect = event.target.getBoundingClientRect()
        state.cursorPosition.x = Math.round(event.clientX - rect.left)
        state.cursorPosition.y = Math.round(event.clientY - rect.top)
        
        if (state.isDragging.value || state.isResizing.value || state.isRotating.value || state.isSelecting.value) {
          const deltaX = event.clientX - state.dragState.startX
          const deltaY = event.clientY - state.dragState.startY
          
          if (state.dragState.type === 'move' && state.dragState.element) {
            // 拖动设计元素
            if (state.dragState.element.type) {
              let hasCollision = false
              
              state.dragState.elements.forEach(element => {
                let newX = element.originalX + deltaX
                let newY = element.originalY + deltaY
                
                // 网格对齐
                if (state.collisionModes.snapToGrid) {
                  newX = Math.round(newX / 10) * 10
                  newY = Math.round(newY / 10) * 10
                }
                
                // 边界限制
                newX = Math.max(0, Math.min(
                  newX,
                  state.boxSize.value.width - element.width
                ))
                newY = Math.max(0, Math.min(
                  newY,
                  state.boxSize.value.height - element.height
                ))
                
                // 临时更新位置
                element.x = newX
                element.y = newY
              })
              
              // 检查碰撞
              if (state.collisionEnabled.value && state.collisionModes.preventOverlap) {
                checkAllCollisions()
                if (state.dragState.elements.some(el => el.colliding)) {
                  hasCollision = true
                }
              }
              
              if (hasCollision) {
                // 回滚到原始位置
                state.dragState.elements.forEach(element => {
                  element.x = element.originalX
                  element.y = element.originalY
                })
                checkAllCollisions()
              } else {
                // 更新所有距离测量
                state.designElements.value = [...state.designElements.value]
                core.updateAllDistanceMeasurements()
              }
            }
          } else if (state.dragState.type === 'label' && state.dragState.label) {
            // 拖动标签 - 允许移动到画布外
            let newX = state.dragState.originalX + deltaX
            let newY = state.dragState.originalY + deltaY
            
            // 移除边界限制，允许标签移动到画布外
            // 保留一些边界检测，防止标签完全移出可视区域
            const maxOffset = 500 // 允许的最大偏移量
            
            newX = Math.max(-maxOffset, 
                           Math.min(newX, state.boxSize.value.width + maxOffset))
            newY = Math.max(-maxOffset,
                           Math.min(newY, state.boxSize.value.height + maxOffset))
            
            state.dragState.label.x = newX
            state.dragState.label.y = newY
            
            // 触发响应式更新
            state.labels.value = [...state.labels.value]
            
            // 如果标签移动到画布边缘，显示放置区域指示器
            if (canvasContainer.value && boxBoundary.value) {
              const boxRect = boxBoundary.value.getBoundingClientRect()
              const zoomRatio = state.zoom.value / 100
              
              // 计算标签在画布边界内的位置
              const labelInBoxX = state.dragState.label.x * zoomRatio
              const labelInBoxY = state.dragState.label.y * zoomRatio
              
              // 检查标签是否在画布边界外
              const isOutsideBox = 
                labelInBoxX < -10 || 
                labelInBoxY < -10 || 
                labelInBoxX > boxRect.width + 10 || 
                labelInBoxY > boxRect.height + 10
              
              state.showDropZone.value = isOutsideBox
            }
          } else if (state.dragState.type === 'guide' && state.dragState.guide) {
            // 拖动参考线
            let newPos = state.dragState.guide.type === 'horizontal' ? 
              state.dragState.originalY + deltaY : 
              state.dragState.originalX + deltaX
            
            if (state.dragState.guide.type === 'horizontal') {
              state.dragState.guide.y = Math.max(0, Math.min(newPos, state.boxSize.value.height))
            } else {
              state.dragState.guide.x = Math.max(0, Math.min(newPos, state.boxSize.value.width))
            }
          } else if (state.dragState.type === 'resize' && state.dragState.element) {
            // 调整设计元素大小
            let newWidth = state.dragState.originalWidth
            let newHeight = state.dragState.originalHeight
            let newX = state.dragState.originalX
            let newY = state.dragState.originalY
            
            const direction = state.dragState.resizeDirection
            
            if (direction.includes('r')) {
              newWidth = Math.max(20, state.dragState.originalWidth + deltaX)
            }
            if (direction.includes('l')) {
              newWidth = Math.max(20, state.dragState.originalWidth - deltaX)
              newX = state.dragState.originalX + deltaX
            }
            if (direction.includes('b')) {
              newHeight = Math.max(20, state.dragState.originalHeight + deltaY)
            }
            if (direction.includes('t')) {
              newHeight = Math.max(20, state.dragState.originalHeight - deltaY)
              newY = state.dragState.originalY + deltaY
            }
            
            // 边界限制
            if (newX < 0) {
              newWidth += newX
              newX = 0
            }
            if (newY < 0) {
              newHeight += newY
              newY = 0
            }
            if (newX + newWidth > state.boxSize.value.width) {
              newWidth = state.boxSize.value.width - newX
            }
            if (newY + newHeight > state.boxSize.value.height) {
              newHeight = state.boxSize.value.height - newY
            }
            
            state.dragState.element.x = newX
            state.dragState.element.y = newY
            state.dragState.element.width = newWidth
            state.dragState.element.height = newHeight
            
            // 更新所有距离测量
            state.designElements.value = [...state.designElements.value]
            core.updateAllDistanceMeasurements()
            checkAllCollisions()
          } else if (state.dragState.type === 'rotate' && state.dragState.element) {
            // 旋转元素
            if (state.dragState.centerX && state.dragState.centerY) {
              const dx = event.clientX - state.dragState.centerX
              const dy = event.clientY - state.dragState.centerY
              const currentAngle = Math.atan2(dy, dx) * 180 / Math.PI
              
              // 计算角度差
              let angleDiff = currentAngle - state.dragState.startAngle
              
              // 更新元素旋转角度
              let newRotation = (state.dragState.originalRotation + angleDiff) % 360
              if (newRotation < 0) newRotation += 360
              
              state.dragState.element.rotation = newRotation
            }
          } else if (state.dragState.type === 'select') {
            // 框选
            state.selectionRect.width = event.offsetX - state.selectionRect.x
            state.selectionRect.height = event.offsetY - state.selectionRect.y
          }
          
          // 如果拖动标签并且标签靠近画布边缘，自动滚动画布
          if (state.dragState.type === 'label' && canvasContainer.value) {
            const containerRect = canvasContainer.value.getBoundingClientRect()
            const scrollThreshold = 50 // 滚动阈值
            const scrollSpeed = 10 // 滚动速度
            
            // 检查是否靠近边缘
            if (event.clientX < containerRect.left + scrollThreshold) {
              canvasContainer.value.scrollLeft -= scrollSpeed
            } else if (event.clientX > containerRect.right - scrollThreshold) {
              canvasContainer.value.scrollLeft += scrollSpeed
            }
            
            if (event.clientY < containerRect.top + scrollThreshold) {
              canvasContainer.value.scrollTop -= scrollSpeed
            } else if (event.clientY > containerRect.bottom - scrollThreshold) {
              canvasContainer.value.scrollTop += scrollSpeed
            }
          }
        }
      },
      
      // 处理画布鼠标抬起
      handleCanvasMouseUp: () => {
        if (state.isSelecting.value && state.selectionRect.width !== 0 && state.selectionRect.height !== 0) {
          // 完成框选，选择范围内的元素
          const rect = {
            left: Math.min(state.selectionRect.x, state.selectionRect.x + state.selectionRect.width),
            right: Math.max(state.selectionRect.x, state.selectionRect.x + state.selectionRect.width),
            top: Math.min(state.selectionRect.y, state.selectionRect.y + state.selectionRect.height),
            bottom: Math.max(state.selectionRect.y, state.selectionRect.y + state.selectionRect.height)
          }
          
          const selected = state.designElements.value.filter(element => {
            const elementRect = {
              left: element.x,
              right: element.x + element.width,
              top: element.y,
              bottom: element.y + element.height
            }
            
            return !(
              elementRect.right < rect.left ||
              elementRect.left > rect.right ||
              elementRect.bottom < rect.top ||
              elementRect.top > rect.bottom
            )
          })
          
          state.selectedElements.value = selected
          if (selected.length === 1) {
            state.selectedElementId.value = selected[0].id
          } else {
            state.selectedElementId.value = null
          }
        }
        
        // 重置所有拖动状态
        state.isDragging.value = false
        state.isResizing.value = false
        state.isRotating.value = false
        state.isSelecting.value = false
        
        // 总是检查碰撞，确保状态正确
        if (state.dragState.type === 'move' || state.dragState.type === 'resize' || state.dragState.type === 'label') {
          checkAllCollisions()
          // 保存历史状态
          utils.saveHistory()
        }
        
        // 移除拖动样式
        if (state.dragState.elements.length > 0) {
          state.dragState.elements.forEach(el => {
            if (elementRefs[el.id]) {
              elementRefs[el.id].classList.remove('dragging')
            }
          })
        }
        
        if (state.dragState.label && elementRefs[state.dragState.label.id]) {
          elementRefs[state.dragState.label.id].classList.remove('dragging')
        }
        
        // 隐藏放置区域指示器
        state.showDropZone.value = false
        
        state.dragState.type = null
        state.dragState.element = null
        state.dragState.elements = []
        state.dragState.label = null
        state.dragState.guide = null
        state.dragState.resizeDirection = null
        
        state.selectionRect.width = 0
        state.selectionRect.height = 0
      },
      
      // 处理画布滚轮缩放
      handleCanvasWheel: (event) => {
        event.preventDefault()
        if (event.ctrlKey) {
          // Ctrl+滚轮缩放
          const delta = event.deltaY > 0 ? -10 : 10
          const newZoom = Math.max(30, Math.min(300, state.zoom.value + delta))
          state.zoom.value = newZoom
        }
      },
      
      // 获取画布光标
      getCanvasCursor: () => {
        if (state.measuringMode.active) return 'crosshair'
        if (state.labelingMode.active) return 'crosshair'
        if (state.selectionMode) return 'crosshair'
        if (state.isResizing.value) {
          const direction = state.dragState.resizeDirection
          if (direction === 'tl' || direction === 'br') return 'nwse-resize'
          if (direction === 'tr' || direction === 'bl') return 'nesw-resize'
          if (direction === 't' || direction === 'b') return 'ns-resize'
          if (direction === 'l' || direction === 'r') return 'ew-resize'
        }
        if (state.isRotating.value) return 'grabbing'
        if (state.isDragging.value && state.dragState.type === 'label') return 'grabbing'
        return 'default'
      },
      
      // 编辑元素
      editElement: (element) => {
        if (element.type === 'text') {
          const newText = prompt('输入文本:', element.props.text)
          if (newText !== null) {
            element.props.text = newText
            core.updateElement()
          }
        } else if (element.type === 'rectangle' && element.props.label) {
          const newLabel = prompt('输入矩形标签:', element.props.label)
          if (newLabel !== null) {
            element.props.label = newLabel
            core.updateElement()
          }
        }
      },
      
      // 更新元素
      updateElement: () => {
        state.designElements.value = [...state.designElements.value]
        checkAllCollisions()
        core.updateAllDistanceMeasurements()
        utils.saveHistory()
      },
      
      // 更新标签
      updateLabel: () => {
        state.labels.value = [...state.labels.value]
        utils.saveHistory()
      },
      
      // 删除元素
      deleteElement: () => {
        if (state.selectedElementId.value) {
          // 删除相关的测量和标签
          state.distanceMeasurements.value = state.distanceMeasurements.value.filter(d => 
            d.element1Id !== state.selectedElementId.value && d.element2Id !== state.selectedElementId.value
          )
          
          state.labels.value = state.labels.value.filter(l => 
            l.elementId !== state.selectedElementId.value
          )
          
          state.designElements.value = state.designElements.value.filter(el => el.id !== state.selectedElementId.value)
          state.selectedElementId.value = null
          state.selectedElements.value = []
          checkAllCollisions()
          utils.saveHistory()
        }
      },
      
      // 删除选中的多个元素
      deleteSelectedElements: () => {
        if (state.selectedElements.value.length > 0) {
          const ids = state.selectedElements.value.map(el => el.id)
          
          // 删除相关的测量和标签
          state.distanceMeasurements.value = state.distanceMeasurements.value.filter(d => 
            !ids.includes(d.element1Id) && !ids.includes(d.element2Id)
          )
          
          state.labels.value = state.labels.value.filter(l => 
            !ids.includes(l.elementId)
          )
          
          state.designElements.value = state.designElements.value.filter(el => !ids.includes(el.id))
          state.selectedElementId.value = null
          state.selectedElements.value = []
          checkAllCollisions()
          utils.saveHistory()
        }
      },
      
      // 复制元素
      duplicateElement: () => {
        if (computedProps.selectedElement.value) {
          const original = computedProps.selectedElement.value
          const duplicate = JSON.parse(JSON.stringify(original))
          duplicate.id = utils.generateId()
          duplicate.x += 20
          duplicate.y += 20
          state.designElements.value.push(duplicate)
          core.selectDesignElement(duplicate.id)
          checkAllCollisions()
          utils.saveHistory()
        }
      },
      
      // 锁定/解锁元素
      lockElement: (element) => {
        element.locked = !element.locked
        core.updateElement()
      },
      
      // 切换元素可见性
      toggleElementVisibility: (element) => {
        element.hidden = !element.hidden
        core.updateElement()
      },
      
      // 聚焦到元素
      focusOnElement: (element) => {
        // 滚动到元素位置
        if (boxBoundary.value && elementRefs[element.id]) {
          const elementRect = elementRefs[element.id].getBoundingClientRect()
          const containerRect = canvasContainer.value.getBoundingClientRect()
          
          // 计算需要滚动的距离
          const scrollLeft = elementRect.left - containerRect.left - containerRect.width / 2 + elementRect.width / 2
          const scrollTop = elementRect.top - containerRect.top - containerRect.height / 2 + elementRect.height / 2
          
          canvasContainer.value.scrollLeft += scrollLeft
          canvasContainer.value.scrollTop += scrollTop
        }
      },
      
      // 置顶元素
      bringToFront: (element) => {
        const index = state.designElements.value.findIndex(el => el.id === element.id)
        if (index !== -1) {
          const element = state.designElements.value.splice(index, 1)[0]
          state.designElements.value.push(element)
          core.updateElement()
          utils.saveHistory()
        }
      },
      
      // 置底元素
      sendToBack: (element) => {
        const index = state.designElements.value.findIndex(el => el.id === element.id)
        if (index !== -1) {
          const element = state.designElements.value.splice(index, 1)[0]
          state.designElements.value.unshift(element)
          core.updateElement()
          utils.saveHistory()
        }
      },
      
      // 组合选中的元素
      groupSelectedElements: () => {
        if (state.selectedElements.value.length > 1) {
          // 这里可以实现组合功能
          alert('组合功能开发中...')
        }
      },
      
      // 对齐选中的元素
      alignSelectedElements: (alignment) => {
        if (state.selectedElements.value.length < 2) return
        
        const elements = state.selectedElements.value
        
        let reference = null
        if (computedProps.selectedElement.value && elements.some(el => el.id === computedProps.selectedElement.value.id)) {
          reference = computedProps.selectedElement.value
        } else {
          reference = elements[0]
        }
        
        elements.forEach(element => {
          if (element.id === reference.id) return
          
          switch (alignment) {
            case 'left':
              element.x = reference.x
              break
            case 'center':
              element.x = reference.x + (reference.width - element.width) / 2
              break
            case 'right':
              element.x = reference.x + reference.width - element.width
              break
            case 'top':
              element.y = reference.y
              break
            case 'middle':
              element.y = reference.y + (reference.height - element.height) / 2
              break
            case 'bottom':
              element.y = reference.y + reference.height - element.height
              break
          }
        })
        
        core.updateElement()
        utils.saveHistory()
      },
      
      // 分布选中的元素
      distributeSelectedElements: (direction) => {
        if (state.selectedElements.value.length < 3) return
        
        const elements = [...state.selectedElements.value]
        
        if (direction === 'horizontal') {
          elements.sort((a, b) => a.x - b.x)
          const totalWidth = elements[elements.length - 1].x - elements[0].x
          const spacing = totalWidth / (elements.length - 1)
          
          for (let i = 1; i < elements.length - 1; i++) {
            elements[i].x = elements[0].x + spacing * i
          }
        } else if (direction === 'vertical') {
          elements.sort((a, b) => a.y - b.y)
          const totalHeight = elements[elements.length - 1].y - elements[0].y
          const spacing = totalHeight / (elements.length - 1)
          
          for (let i = 1; i < elements.length - 1; i++) {
            elements[i].y = elements[0].y + spacing * i
          }
        }
        
        core.updateElement()
        utils.saveHistory()
      },
      
      // 缩放控制
      zoomIn: () => {
        if (state.zoom.value < 300) state.zoom.value += 10
      },
      
      zoomOut: () => {
        if (state.zoom.value > 30) state.zoom.value -= 10
      },
      
      resetZoom: () => {
        state.zoom.value = 100
      },
      
      // 切换网格
      toggleGrid: () => {
        state.showGrid.value = !state.showGrid.value
      },
      
      // 切换标尺
      toggleRulers: () => {
        state.showRulers.value = !state.showRulers.value
      },
      
      // 切换参考线
      toggleGuides: () => {
        state.showGuides.value = !state.showGuides.value
      },
      
      // 切换标签显示
      toggleLabelsVisible: () => {
        state.labelsVisible.value = !state.labelsVisible.value
      },
      
      // 居中显示
      centerView: () => {
        if (canvasContainer.value && boxBoundary.value) {
          const containerRect = canvasContainer.value.getBoundingClientRect()
          const boxRect = boxBoundary.value.getBoundingClientRect()
          
          canvasContainer.value.scrollLeft = boxRect.left - containerRect.left - containerRect.width / 2 + boxRect.width / 2
          canvasContainer.value.scrollTop = boxRect.top - containerRect.top - containerRect.height / 2 + boxRect.height / 2
        }
      },
      
      // 设置箱型尺寸
      setBoxSize: (sizeId) => {
        state.selectedSize.value = sizeId
        if (sizeId === 'custom') {
          core.applyCustomSize()
        } else {
          const preset = state.sizePresets.find(p => p.id === sizeId)
          if (preset) {
            state.boxSize.value = { width: preset.width, height: preset.height }
            state.customWidth.value = preset.width
            state.customHeight.value = preset.height
            checkAllCollisions()
          }
        }
      },
      
      // 应用自定义尺寸
      applyCustomSize: () => {
        if (state.selectedSize.value === 'custom') {
          state.boxSize.value = {
            width: Math.max(50, Math.min(2000, state.customWidth.value)),
            height: Math.max(50, Math.min(2000, state.customHeight.value))
          }
        }
        checkAllCollisions()
      },
      
      // 切换碰撞检测
      toggleCollision: () => {
        checkAllCollisions()
      },
      
      // 更新边距
      updateMargin: () => {
        checkAllCollisions()
      },
      
      // 样式函数
      getElementStyle: (element) => {
        const style = {
          left: element.x + 'px',
          top: element.y + 'px',
          cursor: element.locked ? 'not-allowed' : 'move',
          opacity: element.opacity || 1,
          transform: element.rotation ? `rotate(${element.rotation}deg)` : 'none',
          transformOrigin: 'center center'
        }
        
        style.width = element.width + 'px'
        style.height = element.height + 'px'
        
        if (element.type === 'text') {
          style.fontSize = element.props.fontSize + 'px'
          style.color = element.props.color
          style.fontWeight = element.props.fontWeight
          style.textAlign = element.props.textAlign
          style.fontFamily = element.props.fontFamily
          style.display = 'flex'
          style.alignItems = 'center'
          style.justifyContent = element.props.textAlign || 'center'
        } else if (element.type === 'rectangle') {
          style.border = `${element.props.strokeWidth || 2}px solid ${element.props.strokeColor}`
          style.backgroundColor = element.props.fillColor
          style.borderRadius = (element.props.borderRadius || 0) + 'px'
        } else if (element.type === 'circle') {
          style.border = `${element.props.strokeWidth || 2}px solid ${element.props.strokeColor}`
          style.backgroundColor = element.props.fillColor
          style.borderRadius = '50%'
        } else if (element.type === 'line') {
          style.backgroundColor = element.props.color
          style.border = 'none'
          style.height = (element.props.width || 2) + 'px'
        }
        
        if (element.hidden) {
          style.opacity = 0.3
        }
        
        return style
      },
      
      // 安全边距样式
      getMarginStyle: (element) => {
        return {
          left: -state.marginSize.value + 'px',
          top: -state.marginSize.value + 'px',
          width: (element.width + state.marginSize.value * 2) + 'px',
          height: (element.height + state.marginSize.value * 2) + 'px'
        }
      },
      
      // 距离测量样式
      getDistanceStyle: (distance) => {
        if (!distance.visible) {
          return { display: 'none' }
        }
        
        const startX = distance.startX
        const startY = distance.startY
        const endX = distance.endX
        const endY = distance.endY
        
        const dx = endX - startX
        const dy = endY - startY
        const length = Math.sqrt(dx * dx + dy * dy)
        
        let angle = 0
        if (distance.type === 'vertical') {
          angle = 90
        } else if (distance.type === 'horizontal') {
          angle = 0
        } else {
          angle = Math.atan2(dy, dx) * 180 / Math.PI
        }
        
        return {
          left: startX + 'px',
          top: startY + 'px',
          width: length + 'px',
          transform: `rotate(${angle}deg)`,
          transformOrigin: 'left center'
        }
      },
      
      // 格式化距离显示
      formatDistance: (distance) => {
        if (distance.type === 'overlap') {
          return '0px (重叠)'
        }
        return `${Math.round(distance.value)}px`
      },
      
      // 标签样式
      getLabelStyle: (label) => {
        if (!state.labelsVisible.value && !label.visible) {
          return {
            display: 'none'
          }
        }
        
        return {
          left: label.x + 'px',
          top: label.y + 'px',
          width: label.width + 'px',
          height: label.height + 'px',
          backgroundColor: label.color,
          opacity: label.visible ? 1 : 0.5
        }
      },
      
      // 标签连接线样式
      getLabelConnectorStyle: (label) => {
        const targetElement = state.designElements.value.find(el => el.id === label.elementId)
        if (!targetElement) return {}
        
        const targetX = targetElement.x + targetElement.width / 2
        const targetY = targetElement.y + targetElement.height / 2
        
        const dx = label.x - targetX
        const dy = label.y - targetY
        const length = Math.sqrt(dx * dx + dy * dy)
        const angle = Math.atan2(dy, dx) * 180 / Math.PI
        
        // 如果标签在画布外，连接线从画布边缘开始
        const connectorLength = Math.min(length, label.connectorLength || 30)
        
        return {
          left: targetX + 'px',
          top: targetY + 'px',
          width: connectorLength + 'px',
          transform: `rotate(${angle}deg)`,
          transformOrigin: 'left center'
        }
      },
      
      // 测量辅助线样式
      getGuideLineStyle: () => {
        if (state.measuringMode.selectedElements.length !== 1) return {}
        
        const element = state.measuringMode.selectedElements[0]
        const centerX = element.x + element.width / 2
        const centerY = element.y + element.height / 2
        
        return {
          left: centerX + 'px',
          top: centerY + 'px'
        }
      },
      
      // 标签放置预览线样式
      getPreviewLineStyle: () => {
        if (!state.labelingMode.targetElementId || !state.labelingMode.placementPosition) return {}
        
        const targetElement = state.designElements.value.find(el => el.id === state.labelingMode.targetElementId)
        if (!targetElement) return {}
        
        const targetX = targetElement.x + targetElement.width / 2
        const targetY = targetElement.y + targetElement.height / 2
        
        const dx = state.labelingMode.placementPosition.x - targetX
        const dy = state.labelingMode.placementPosition.y - targetY
        const length = Math.sqrt(dx * dx + dy * dy)
        const angle = Math.atan2(dy, dx) * 180 / Math.PI
        
        return {
          left: targetX + 'px',
          top: targetY + 'px',
          width: length + 'px',
          transform: `rotate(${angle}deg)`,
          transformOrigin: 'left center'
        }
      },
      
      // 获取元素提示
      getElementTooltip: (element) => {
        let tooltip = `${utils.getElementTypeName(element.type)}`
        
        if (element.type === 'text') {
          tooltip += `: ${element.props.text}`
        } else if (element.type === 'rectangle' && element.props.label) {
          tooltip += `: ${element.props.label}`
        } else if (element.type === 'image' && element.props.name) {
          tooltip += `: ${element.props.name}`
        }
        
        if (element.locked) {
          tooltip += '\n🔒 已锁定'
        }
        
        if (element.hidden) {
          tooltip += '\n👁️‍🗨️ 已隐藏'
        }
        
        if (element.colliding) {
          tooltip += '\n⚠️ 与其他元素重叠或超出边界'
        }
        
        return tooltip
      },
      
      // 操作历史（修复循环引用问题）
      undo: () => {
        if (state.history.past.length > 0) {
          const current = {
            elements: state.designElements.value.map(el => {
              const { colliding, collisions, ...rest } = el
              return {
                ...rest,
                colliding: false,
                collisions: []
              }
            }),
            measurements: JSON.parse(JSON.stringify(state.distanceMeasurements.value)),
            labels: JSON.parse(JSON.stringify(state.labels.value))
          }
          
          state.history.future.push(current)
          const snapshot = state.history.past.pop()
          
          state.designElements.value = snapshot.elements
          state.distanceMeasurements.value = snapshot.measurements
          state.labels.value = snapshot.labels
          
          state.selectedElementId.value = null
          state.selectedDistanceId.value = null
          state.selectedLabelId.value = null
          state.selectedElements.value = []
          
          // 重新计算碰撞
          checkAllCollisions()
        }
      },
      
      redo: () => {
        if (state.history.future.length > 0) {
          const current = {
            elements: state.designElements.value.map(el => {
              const { colliding, collisions, ...rest } = el
              return {
                ...rest,
                colliding: false,
                collisions: []
              }
            }),
            measurements: JSON.parse(JSON.stringify(state.distanceMeasurements.value)),
            labels: JSON.parse(JSON.stringify(state.labels.value))
          }
          
          state.history.past.push(current)
          const snapshot = state.history.future.pop()
          
          state.designElements.value = snapshot.elements
          state.distanceMeasurements.value = snapshot.measurements
          state.labels.value = snapshot.labels
          
          state.selectedElementId.value = null
          state.selectedDistanceId.value = null
          state.selectedLabelId.value = null
          state.selectedElements.value = []
          
          // 重新计算碰撞
          checkAllCollisions()
        }
      },
      
      // 全屏切换
      toggleFullscreen: () => {
        if (!document.fullscreenElement) {
          document.documentElement.requestFullscreen()
          state.isFullscreen.value = true
        } else {
          document.exitFullscreen()
          state.isFullscreen.value = false
        }
      },
      
      // 上传图片
      uploadImage: () => {
        const input = document.createElement('input')
        input.type = 'file'
        input.accept = 'image/*'
        
        input.onchange = (e) => {
          const file = e.target.files[0]
          if (file) {
            const reader = new FileReader()
            reader.onload = (e) => {
              if (computedProps.selectedElement.value && computedProps.selectedElement.value.type === 'image') {
                computedProps.selectedElement.value.props.url = e.target.result
                computedProps.selectedElement.value.props.name = file.name
                core.updateElement()
              }
            }
            reader.readAsDataURL(file)
          }
        }
        
        input.click()
      },
      
      // 项目操作（修复循环引用问题）
      saveProject: () => {
        const project = {
          name: '箱面设计',
          version: '2.0',
          boxSize: state.boxSize.value,
          customWidth: state.customWidth.value,
          customHeight: state.customHeight.value,
          selectedSize: state.selectedSize.value,
          collisionEnabled: state.collisionEnabled.value,
          collisionModes: state.collisionModes,
          marginSize: state.marginSize.value,
          // 保存元素时移除碰撞信息中的循环引用
          elements: state.designElements.value.map(el => {
            const elementCopy = { ...el }
            if (elementCopy.collisions) {
              elementCopy.collisions = elementCopy.collisions.map(collision => {
                const { element, ...rest } = collision
                return {
                  ...rest,
                  elementId: collision.elementId
                }
              })
            }
            return elementCopy
          }),
          distanceMeasurements: state.distanceMeasurements.value,
          labels: state.labels.value,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        }
        
        // 添加到最近项目
        const recentProject = {
          id: utils.generateId(),
          name: project.name,
          date: project.createdAt,
          elements: project.elements.length
        }
        
        state.recentProjects.value = [recentProject, ...state.recentProjects.value.slice(0, 4)]
        localStorage.setItem('recentProjects', JSON.stringify(state.recentProjects.value))
        
        const dataStr = JSON.stringify(project, null, 2)
        const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr)
        const link = document.createElement('a')
        link.download = `design-${new Date().getTime()}.boxdesign`
        link.href = dataUri
        link.click()
      },
      
      loadProject: () => {
        const input = document.createElement('input')
        input.type = 'file'
        input.accept = '.boxdesign'
        
        input.onchange = (e) => {
          const file = e.target.files[0]
          const reader = new FileReader()
          
          reader.onload = (e) => {
            try {
              const project = JSON.parse(e.target.result)
              
              // 验证项目版本
              if (!project.version || project.version.startsWith('1.')) {
                // 兼容旧版本
                state.designElements.value = project.elements || []
                state.boxSize.value = project.boxSize || { width: 400, height: 300 }
                state.customWidth.value = project.customWidth || state.boxSize.value.width
                state.customHeight.value = project.customHeight || state.boxSize.value.height
                state.selectedSize.value = project.selectedSize || 'standard'
                state.collisionEnabled.value = project.collisionEnabled !== undefined ? project.collisionEnabled : true
                if (project.collisionModes) {
                  Object.assign(state.collisionModes, project.collisionModes)
                }
                state.distanceMeasurements.value = project.distanceMeasurements || []
                state.labels.value = project.labels || []
              } else {
                // 新版本
                state.designElements.value = project.elements || []
                state.boxSize.value = project.boxSize || { width: 400, height: 300 }
                state.customWidth.value = project.customWidth || state.boxSize.value.width
                state.customHeight.value = project.customHeight || state.boxSize.value.height
                state.selectedSize.value = project.selectedSize || 'standard'
                state.collisionEnabled.value = project.collisionEnabled !== undefined ? project.collisionEnabled : true
                if (project.collisionModes) {
                  Object.assign(state.collisionModes, project.collisionModes)
                }
                state.marginSize.value = project.marginSize || 10
                state.distanceMeasurements.value = project.distanceMeasurements || []
                state.labels.value = project.labels || []
              }
              
              state.selectedElementId.value = null
              state.selectedDistanceId.value = null
              state.selectedLabelId.value = null
              state.selectedElements.value = []
              
              // 重新计算碰撞
              checkAllCollisions()
              
              // 添加到最近项目
              const recentProject = {
                id: utils.generateId(),
                name: project.name || '未命名项目',
                date: new Date().toISOString(),
                elements: project.elements.length
              }
              
              state.recentProjects.value = [recentProject, ...state.recentProjects.value.slice(0, 4)]
              localStorage.setItem('recentProjects', JSON.stringify(state.recentProjects.value))
              
              alert('项目加载成功')
            } catch (err) {
              console.error('加载项目失败:', err)
              alert('文件格式错误或版本不兼容')
            }
          }
          
          reader.readAsText(file)
        }
        
        input.click()
      },
      
      // 加载最近项目
      loadRecentProject: (project) => {
        // 这里可以从本地存储加载具体项目数据
        const savedProjects = localStorage.getItem('designProjects')
        if (savedProjects) {
          try {
            const projects = JSON.parse(savedProjects)
            const foundProject = projects.find(p => p.id === project.id)
            if (foundProject) {
              state.designElements.value = foundProject.elements || []
              state.boxSize.value = foundProject.boxSize || { width: 400, height: 300 }
              state.distanceMeasurements.value = foundProject.distanceMeasurements || []
              state.labels.value = foundProject.labels || []
              // 重新计算碰撞
              checkAllCollisions()
              alert(`项目 "${project.name}" 加载成功`)
            } else {
              alert('项目数据已丢失')
            }
          } catch (err) {
            console.error('加载项目失败:', err)
            alert('加载项目失败')
          }
        } else {
          alert('没有找到项目数据')
        }
      },
      
      // 导出设计
      exportDesign: () => {
        state.showExportPanel.value = true
      },
      
      // 执行导出
      doExport: () => {
        alert(`导出为 ${state.exportFormat.value.toUpperCase()} 格式`)
        state.showExportPanel.value = false
      },
      
      // 导出测量数据
      exportMeasurements: () => {
        const data = state.distanceMeasurements.value.map(distance => ({
          起点: core.getElementName(distance.element1Id),
          终点: core.getElementName(distance.element2Id),
          类型: utils.getDistanceTypeName(distance.type),
          距离: core.formatDistance(distance),
          水平偏移: distance.horizontalOffset || 0,
          垂直偏移: distance.verticalOffset || 0
        }))
        
        const csv = '数据,起点,终点,类型,距离(px),水平偏移(px),垂直偏移(px)\n' +
          data.map(d => Object.values(d).join(',')).join('\n')
        
        const blob = new Blob([csv], { type: 'text/csv' })
        const url = window.URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = `measurements-${new Date().getTime()}.csv`
        link.click()
      },
      
      // 显示测量面板
      showMeasurementsPanelFn: () => {
        state.showMeasurementsPanel.value = !state.showMeasurementsPanel.value
        if (state.showMeasurementsPanel.value) {
          state.showLabelsPanel.value = false
        }
      },
      
      // 显示标签面板
      showLabelsPanelFn: () => {
        state.showLabelsPanel.value = !state.showLabelsPanel.value
        if (state.showLabelsPanel.value) {
          state.showMeasurementsPanel.value = false
        }
      }
    }

    // 初始化
    onMounted(() => {
      // 添加示例元素
      state.designElements.value = [
        {
          id: utils.generateId(),
          type: 'text',
          x: 50,
          y: 50,
          width: 120,
          height: 40,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            text: '产品名称',
            fontSize: 18,
            color: '#000000',
            fontWeight: 'bold',
            textAlign: 'center',
            fontFamily: 'Arial, sans-serif'
          }
        },
        {
          id: utils.generateId(),
          type: 'rectangle',
          x: 200,
          y: 50,
          width: 150,
          height: 100,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            label: '重要信息',
            fontSize: 16,
            labelColor: '#000000',
            fillColor: 'rgba(255, 255, 0, 0.1)',
            strokeColor: '#ff9900',
            strokeWidth: 2,
            borderRadius: 8
          }
        },
        {
          id: utils.generateId(),
          type: 'qrcode',
          x: 200,
          y: 200,
          width: 100,
          height: 100,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            content: 'https://example.com',
            showLabel: true,
            label: '二维码',
            foregroundColor: '#000000',
            backgroundColor: '#ffffff'
          }
        },
        {
          id: utils.generateId(),
          type: 'line',
          x: 50,
          y: 180,
          width: 100,
          height: 2,
          rotation: 0,
          opacity: 1,
          hidden: false,
          locked: false,
          colliding: false,
          collisions: [],
          props: {
            color: '#000000',
            width: 2,
            style: 'solid'
          }
        }
      ]
      
      // 加载最近项目
      const savedProjects = localStorage.getItem('recentProjects')
      if (savedProjects) {
        try {
          state.recentProjects.value = JSON.parse(savedProjects)
        } catch (e) {
          console.error('加载最近项目失败:', e)
        }
      }
      
      // 初始计算碰撞
      checkAllCollisions()
      
      // 监听全局事件
      document.addEventListener('mouseup', core.handleCanvasMouseUp)
      document.addEventListener('keydown', (e) => {
        // 快捷键支持
        if (e.ctrlKey || e.metaKey) {
          switch (e.key.toLowerCase()) {
            case 'z':
              if (e.shiftKey) {
                core.redo()
              } else {
                core.undo()
              }
              e.preventDefault()
              break
            case 'y':
              core.redo()
              e.preventDefault()
              break
            case 's':
              core.saveProject()
              e.preventDefault()
              break
            case 'o':
              core.loadProject()
              e.preventDefault()
              break
            case 'g':
              state.showGrid.value = !state.showGrid.value
              e.preventDefault()
              break
            case 'd':
              if (computedProps.selectedElement.value) {
                core.duplicateElement()
              }
              e.preventDefault()
              break
            case 'delete':
            case 'backspace':
              if (computedProps.selectedElement.value) {
                core.deleteElement()
              }
              e.preventDefault()
              break
          }
        } else if (e.key === 'Escape') {
          // 取消所有选择和模式
          state.selectedElementId.value = null
          state.selectedDistanceId.value = null
          state.selectedLabelId.value = null
          state.selectedElements.value = []
          state.measuringMode.active = false
          state.labelingMode.active = false
          state.selectionMode = false
          state.measuringMode.selectedElements = []
        }
      })
      
      // 监听全屏变化
      document.addEventListener('fullscreenchange', () => {
        state.isFullscreen.value = !!document.fullscreenElement
      })
    })
    
    onUnmounted(() => {
      document.removeEventListener('mouseup', core.handleCanvasMouseUp)
    })

    // 返回所有需要暴露的内容
    return {
      // 状态
      ...state,
      ...computedProps,
      
      // 工具函数
      formatDate: utils.formatDate,
      getElementTypeName: utils.getElementTypeName,
      getDistanceTypeName: utils.getDistanceTypeName,
      isMultiSelected: utils.isMultiSelected,
      
      // 核心功能
      ...core,
      
      // 计算属性
      selectedElement: computedProps.selectedElement,
      selectedDistance: computedProps.selectedDistance,
      selectedLabel: computedProps.selectedLabel,
      collisionStats: computedProps.collisionStats,
      multiStats: computedProps.multiStats,
      canUndo: computedProps.canUndo,
      canRedo: computedProps.canRedo,
      horizontalRulerMarks: computedProps.horizontalRulerMarks,
      verticalRulerMarks: computedProps.verticalRulerMarks,
      selectionRectStyle: computedProps.selectionRectStyle,
      previewBoxStyle: computedProps.previewBoxStyle,
      
      // 引用和工具
      canvasContainer,
      boxBoundary,
      setElementRef,
      
      // 碰撞检测函数
      checkAllCollisions,
      getCollisions // 暴露修复后的碰撞获取函数
    }
  }
}
